import type { SchematicDocument } from '../domain/schematic'

const CORNERS = [
  [-0.5, -0.5, -0.5], [0.5, -0.5, -0.5], [0.5, 0.5, -0.5], [-0.5, 0.5, -0.5],
  [-0.5, -0.5, 0.5], [0.5, -0.5, 0.5], [0.5, 0.5, 0.5], [-0.5, 0.5, 0.5],
] as const
const FACES = [[0, 1, 2, 3], [5, 4, 7, 6], [4, 0, 3, 7], [1, 5, 6, 2], [3, 2, 6, 7], [4, 5, 1, 0]] as const

export function createPly(schematic: SchematicDocument, includeAlpha = true): string {
  const header = [
    'ply', 'format ascii 1.0', 'comment Generated by Player Statue Builder Web',
    `element vertex ${schematic.blocks.length * 8}`,
    'property float x', 'property float y', 'property float z',
    'property uchar red', 'property uchar green', 'property uchar blue',
    ...(includeAlpha ? ['property uchar alpha'] : []),
    `element face ${schematic.blocks.length * 6}`, 'property list uchar int vertex_indices', 'end_header',
  ]
  const vertices: string[] = []
  const faces: string[] = []
  schematic.blocks.forEach((block, blockIndex) => {
    const entry = schematic.palette[block.palette]
    if (!entry) throw new Error(`Block references missing palette index ${block.palette}`)
    const color = [1, 3, 5].map((offset) => Number.parseInt(entry.color.slice(offset, offset + 2), 16))
    const components = includeAlpha ? [...color, Math.round(entry.opacity * 255)] : color
    for (const corner of CORNERS) vertices.push(`${block.x + corner[0]} ${block.y + corner[1]} ${block.z + corner[2]} ${components.join(' ')}`)
    for (const face of FACES) faces.push(`4 ${face.map((index) => index + blockIndex * 8).join(' ')}`)
  })
  return [...header, ...vertices, ...faces, ''].join('\n')
}

export function createPlyCompat(schematic: SchematicDocument): string {
  return createPly(schematic, false)
}